const fs = require('node:fs');
const path = require('node:path');

const directory = path.resolve(__dirname, '..', 'database');
const sources = {
  cameraAlerts: 'camera_alerts.sql',
  reportNotifications: 'report_notifications.sql',
  enrolledFaces: 'enrolled_faces.sql',
  announcementReads: 'announcement_reads.sql'
};
const schemas = Object.fromEntries(Object.entries(sources).map(([key, file]) => [
  key, fs.readFileSync(path.join(directory, file), 'utf8').replace(/\r\n/g, '\n')
]));

fs.writeFileSync(path.join(directory, 'runtime-schemas.js'),
  '// Generated by scripts/generate-runtime-schemas.cjs. Edit the SQL sources instead.\n'
  + `module.exports = ${JSON.stringify(schemas, null, 2)};\n`);
console.log('Generated database/runtime-schemas.js');
